@pytest.mark.valid_from("Amsterdam")
def test_block_state_gas_accumulator_divergence(
    blockchain_test: BlockchainTestFiller,
    pre: Alloc,
    fork: Fork,
) -> None:
    """Verify block gas_used with cumulative state from fuzz txs."""
    blockchain_test(
        genesis_environment=Environment(gas_limit=60_000_000),
        pre=pre,
        blocks=[
            Block(
                txs=[
                    Transaction(
                        to=to,
                        data=bytes.fromhex(data[2:])
                        if data != "0x"
                        else b"",
                        value=value,
                        gas_limit=gas,
                        sender=pre.fund_eoa(10**21),
                    )
                    for to, gas, value, data in BLOCK17_TXS
                ],
                gas_limit=60_000_000,
            ),
        ],
        post={},
    )
